buck_converter.script:
% Simulink.SimulationInput padrao MCP
modelName = 'Buck_DCDC_Model';
simIn = Simulink.SimulationInput(modelName);
simIn = simIn.setVariable('Vin', 400.0);
simIn = simIn.setVariable('DutyCycle', 0.12);
simIn = simIn.setModelParameter('SaveFormat', 'Dataset');
simOut = sim(simIn);

