pid_controller.script:
% Controle PI/PID via SimulationInput (MCP Core)
modelName = 'ClosedLoop_PID_Torque';
simIn = Simulink.SimulationInput(modelName);
simIn = simIn.setVariable('Kp_gain', 1.25);
simIn = simIn.setVariable('Ki_gain', 35.0);
simIn = simIn.setModelParameter('SaveFormat', 'Dataset');
simOut = sim(simIn);
